package com.acme.core.infrastructure.persistence;

import com.acme.core.application.mysqlcustomer.MySqlCustomerPort;
import com.acme.core.application.mysqlcustomer.MySqlCustomerService;
import com.acme.core.application.organization.DepartmentPort;
import com.acme.core.application.dictionary.DictionaryPort;
import com.acme.core.infrastructure.persistence.mapper.MySqlCustomerMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * MySqlCustomer bean wiring (generated by engineering-platform Generic Module Generator).
 */
@Configuration
public class MySqlCustomerBeansConfig {

    @Bean
    public MySqlCustomerPort mySqlCustomerPort(MySqlCustomerMapper mapper, DepartmentPort departmentPort) {
        return new MybatisMySqlCustomerRepository(mapper, departmentPort);
    }

    @Bean
    public MySqlCustomerService mySqlCustomerService(MySqlCustomerPort port, DictionaryPort dictionaryPort) {
        return new MySqlCustomerService(port, dictionaryPort);
    }
}
